contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public {
        c.NETM(); if (__ESBMC_reverted()) return;
        uint balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint distBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.burn(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted == (amount > balBefore) &&
            (reverted || (
                c.balanceOf(address(this)) == balBefore - amount &&
                c.totalSupply() == supplyBefore - amount &&
                c.totalDistributed() == distBefore - amount
            ))
        );
    }
    receive() external payable {}
}

